begin;

-- Oil supplier accounting is a settlement layer over existing authoritative Oil sources.
-- It never creates Oil stock, Oil vehicle expense, Voucher, or Workshop records.
do $$
declare v_bad text;
begin
  if to_regclass('public.oil_shops') is null or to_regclass('public.oil_purchases') is null
     or to_regclass('public.oil_vehicle_entries') is null or to_regclass('public.cashbook_entries') is null then
    raise exception 'OIL_SUPPLIER_PREFLIGHT: Oil Phase 1 and Cashbook tables are required';
  end if;
  if to_regprocedure('public.current_user_adda_id()') is null or to_regprocedure('public.current_user_role()') is null
     or to_regprocedure('public.is_super_admin()') is null then
    raise exception 'OIL_SUPPLIER_PREFLIGHT: tenant helper functions are required';
  end if;
  if exists(select 1 from public.oil_purchases where coalesce(paid_amount,0) <> 0) then
    raise exception 'OIL_SUPPLIER_PREFLIGHT: historical oil_purchases.paid_amount is non-zero; reconcile it without guessing before deployment';
  end if;
  select string_agg(c.relname, ', ') into v_bad from pg_class c join pg_namespace n on n.oid=c.relnamespace
   where n.nspname='public' and c.relname in ('oil_supplier_bills','oil_supplier_payments','oil_supplier_payment_allocations') and c.relkind not in ('r','p');
  if v_bad is not null then raise exception 'OIL_SUPPLIER_PREFLIGHT: conflicting objects: %',v_bad; end if;
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in
    ('rebuild_oil_supplier_accounting','save_oil_supplier_payment','delete_oil_supplier_payment')) then
    raise exception 'OIL_SUPPLIER_PREFLIGHT: unexpected Oil supplier RPC overload exists';
  end if;
  if exists(select 1 from public.cashbook_entries where reference_type='oil_supplier_payment' group by reference_type,reference_id having count(*)>1) then
    raise exception 'OIL_SUPPLIER_PREFLIGHT: duplicate oil_supplier_payment Cashbook references exist';
  end if;
end $$;

create table public.oil_supplier_bills (
  id uuid primary key default gen_random_uuid(),
  adda_id uuid not null references public.addas(id) on delete restrict,
  oil_shop_id uuid not null references public.oil_shops(id) on delete restrict,
  source_type text not null check(source_type in ('oil_purchase','oil_vehicle_entry')),
  oil_purchase_id uuid references public.oil_purchases(id) on delete cascade,
  oil_vehicle_entry_id uuid references public.oil_vehicle_entries(id) on delete cascade,
  bill_date date not null,
  bill_no text,
  amount numeric not null check(amount>0),
  paid_amount numeric not null default 0 check(paid_amount>=0),
  remaining_amount numeric not null check(remaining_amount>=0),
  payment_status text not null default 'unpaid' check(payment_status in ('unpaid','partial','paid')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  constraint oil_supplier_bill_source_check check(
    (source_type='oil_purchase' and oil_purchase_id is not null and oil_vehicle_entry_id is null) or
    (source_type='oil_vehicle_entry' and oil_vehicle_entry_id is not null and oil_purchase_id is null))
);
create unique index oil_supplier_bills_purchase_uidx on public.oil_supplier_bills(oil_purchase_id) where oil_purchase_id is not null;
create unique index oil_supplier_bills_vehicle_entry_uidx on public.oil_supplier_bills(oil_vehicle_entry_id) where oil_vehicle_entry_id is not null;
create index oil_supplier_bills_shop_date_idx on public.oil_supplier_bills(oil_shop_id,bill_date,id);

create table public.oil_supplier_payments (
  id bigint generated by default as identity primary key,
  oil_shop_id uuid not null references public.oil_shops(id) on delete restrict,
  payment_date date not null, amount numeric not null check(amount>=0), payment_method text,
  reference_no text, remarks text, created_at timestamptz not null default now(),
  advance_used numeric not null default 0 check(advance_used>=0), payment_now numeric not null default 0 check(payment_now>=0),
  opening_applied numeric not null default 0 check(opening_applied>=0), advance_created numeric not null default 0 check(advance_created>=0),
  available_advance_before numeric not null default 0 check(available_advance_before>=0),
  current_payable_before numeric not null default 0 check(current_payable_before>=0),
  remaining_payable numeric not null default 0 check(remaining_payable>=0),
  remaining_advance numeric not null default 0 check(remaining_advance>=0),
  settlement_status text not null default 'paid' check(settlement_status in ('payable','advance','paid')),
  accounting_version smallint not null default 1
);
create index oil_supplier_payments_shop_date_idx on public.oil_supplier_payments(oil_shop_id,payment_date,created_at,id);

create table public.oil_supplier_payment_allocations (
  id uuid primary key default gen_random_uuid(), payment_id bigint not null references public.oil_supplier_payments(id) on delete cascade,
  supplier_bill_id uuid not null references public.oil_supplier_bills(id) on delete cascade,
  amount numeric not null check(amount>0), created_at timestamptz not null default now(), unique(payment_id,supplier_bill_id)
);
create index oil_supplier_allocations_bill_idx on public.oil_supplier_payment_allocations(supplier_bill_id);
create unique index cashbook_entries_oil_supplier_reference_uidx on public.cashbook_entries(reference_type,reference_id)
  where reference_type='oil_supplier_payment' and reference_id is not null;

alter table public.oil_supplier_bills enable row level security;
alter table public.oil_supplier_payments enable row level security;
alter table public.oil_supplier_payment_allocations enable row level security;
create policy oil_supplier_bills_select on public.oil_supplier_bills for select to authenticated using((select public.is_super_admin()) or adda_id=(select public.current_user_adda_id()));
create policy oil_supplier_payments_select on public.oil_supplier_payments for select to authenticated using(exists(select 1 from public.oil_shops s where s.id=oil_shop_id and ((select public.is_super_admin()) or s.adda_id=(select public.current_user_adda_id()))));
create policy oil_supplier_allocations_select on public.oil_supplier_payment_allocations for select to authenticated using(exists(select 1 from public.oil_supplier_payments p join public.oil_shops s on s.id=p.oil_shop_id where p.id=payment_id and ((select public.is_super_admin()) or s.adda_id=(select public.current_user_adda_id()))));
revoke all on public.oil_supplier_bills,public.oil_supplier_payments,public.oil_supplier_payment_allocations from anon,authenticated;
grant select on public.oil_supplier_bills,public.oil_supplier_payments,public.oil_supplier_payment_allocations to authenticated;

create function public.rebuild_oil_supplier_accounting(p_oil_shop_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare s record; p record; b record; v_opening numeric; v_advance numeric; v_opening_due numeric; v_payable numeric;
  v_advance_used numeric; v_settlement numeric; v_apply numeric; v_created numeric;
begin
  select * into s from public.oil_shops where id=p_oil_shop_id and shop_type='external_supplier' for update;
  if not found then raise exception 'OIL_SUPPLIER_NOT_FOUND'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_oil_shop_id::text,0));
  perform set_config('ut.oil_supplier_sync','on',true); perform set_config('ut.cashbook_sync','on',true);
  delete from public.oil_supplier_payment_allocations a using public.oil_supplier_payments p where a.payment_id=p.id and p.oil_shop_id=p_oil_shop_id;
  update public.oil_supplier_bills set paid_amount=0,remaining_amount=amount,payment_status='unpaid',updated_at=now() where oil_shop_id=p_oil_shop_id;
  v_opening:=coalesce(s.opening_balance,0); v_opening_due:=greatest(v_opening,0); v_advance:=greatest(-v_opening,0);
  for p in select * from public.oil_supplier_payments where oil_shop_id=p_oil_shop_id order by payment_date,created_at,id for update loop
    select v_opening_due+coalesce(sum(remaining_amount),0) into v_payable from public.oil_supplier_bills where oil_shop_id=p_oil_shop_id;
    v_advance_used:=least(coalesce(p.advance_used,0),v_advance,v_payable);
    v_settlement:=v_advance_used+coalesce(p.payment_now,0); v_advance:=v_advance-v_advance_used; v_created:=0;
    v_apply:=least(v_settlement,v_opening_due); v_opening_due:=v_opening_due-v_apply; v_settlement:=v_settlement-v_apply;
    for b in select * from public.oil_supplier_bills where oil_shop_id=p_oil_shop_id and remaining_amount>0 order by bill_date,created_at,id for update loop
      exit when v_settlement<=0; v_apply:=least(v_settlement,b.remaining_amount);
      insert into public.oil_supplier_payment_allocations(payment_id,supplier_bill_id,amount) values(p.id,b.id,v_apply);
      update public.oil_supplier_bills set paid_amount=paid_amount+v_apply,remaining_amount=remaining_amount-v_apply,
        payment_status=case when remaining_amount-v_apply=0 then 'paid' else 'partial' end,updated_at=now() where id=b.id;
      v_settlement:=v_settlement-v_apply;
    end loop;
    if v_settlement>0 then v_created:=v_settlement;v_advance:=v_advance+v_settlement; end if;
    select v_opening_due+coalesce(sum(remaining_amount),0) into v_payable from public.oil_supplier_bills where oil_shop_id=p_oil_shop_id;
    update public.oil_supplier_payments set advance_used=v_advance_used,amount=v_advance_used+coalesce(payment_now,0),opening_applied=least(v_advance_used+coalesce(payment_now,0),greatest(v_opening,0)),
      advance_created=v_created,available_advance_before=v_advance+v_advance_used-v_created,current_payable_before=v_payable+(v_advance_used+coalesce(payment_now,0)-v_created),
      remaining_payable=v_payable,remaining_advance=v_advance,settlement_status=case when v_payable>0 then 'payable' when v_advance>0 then 'advance' else 'paid' end,accounting_version=1 where id=p.id;
    if coalesce(p.payment_now,0)>0 then
      insert into public.cashbook_entries(entry_date,entry_type,person_type,person_name,payment_method,amount,description,reference_type,reference_id)
      values(p.payment_date,'Cash Out','Other',s.shop_name,coalesce(nullif(p.payment_method,''),'Cash'),p.payment_now,'Oil supplier payment - '||s.shop_name,'oil_supplier_payment',p.id::text)
      on conflict(reference_type,reference_id) where reference_type='oil_supplier_payment' and reference_id is not null do update set entry_date=excluded.entry_date,entry_type=excluded.entry_type,person_type=excluded.person_type,person_name=excluded.person_name,payment_method=excluded.payment_method,amount=excluded.amount,description=excluded.description;
    else delete from public.cashbook_entries where reference_type='oil_supplier_payment' and reference_id=p.id::text; end if;
  end loop;
end $$;

create function public.ut_sync_oil_supplier_source_bill() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_old_shop uuid; v_new_shop uuid; v_id uuid; v_adda uuid; v_date date; v_no text; v_amount numeric;
begin
  perform set_config('ut.oil_supplier_sync','on',true);
  if tg_table_name='oil_purchases' then
    if tg_op<>'INSERT' then v_old_shop:=old.oil_shop_id; delete from public.oil_supplier_bills where oil_purchase_id=old.id; end if;
    if tg_op<>'DELETE' then v_new_shop:=new.oil_shop_id;v_id:=new.id;v_adda:=new.adda_id;v_date:=new.purchase_date;v_no:=new.bill_no;v_amount:=new.total_amount;
      insert into public.oil_supplier_bills(adda_id,oil_shop_id,source_type,oil_purchase_id,bill_date,bill_no,amount,remaining_amount) values(v_adda,v_new_shop,'oil_purchase',v_id,v_date,v_no,v_amount,v_amount); end if;
  else
    if tg_op<>'INSERT' and old.source_type='external_shop' then v_old_shop:=old.oil_shop_id;delete from public.oil_supplier_bills where oil_vehicle_entry_id=old.id;end if;
    if tg_op<>'DELETE' and new.source_type='external_shop' then v_new_shop:=new.oil_shop_id;v_id:=new.id;v_adda:=new.adda_id;v_date:=new.entry_date;v_no:=new.bill_no;v_amount:=new.total_amount;
      insert into public.oil_supplier_bills(adda_id,oil_shop_id,source_type,oil_vehicle_entry_id,bill_date,bill_no,amount,remaining_amount) values(v_adda,v_new_shop,'oil_vehicle_entry',v_id,v_date,v_no,v_amount,v_amount);end if;
  end if;
  if v_old_shop is not null then perform public.rebuild_oil_supplier_accounting(v_old_shop);end if;
  if v_new_shop is not null and v_new_shop is distinct from v_old_shop then perform public.rebuild_oil_supplier_accounting(v_new_shop);end if;
  return case when tg_op='DELETE' then old else new end;
end $$;

create function public.ut_prepare_oil_supplier_source_mutation() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin perform set_config('ut.oil_supplier_sync','on',true);return case when tg_op='DELETE' then old else new end;end $$;

create function public.save_oil_supplier_payment(p_payment_id bigint,p_oil_shop_id uuid,p_payment_date date,p_advance_used numeric,p_payment_now numeric,p_payment_method text,p_reference_no text,p_remarks text) returns bigint
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id bigint;v_adda uuid;v_role text;v_advance numeric:=coalesce(p_advance_used,0);v_now numeric:=coalesce(p_payment_now,0);
begin
  v_role:=public.current_user_role();if auth.uid() is null or v_role not in('super_admin','adda_admin','operator') then raise exception 'AUTHORIZATION_FAILED';end if;
  select adda_id into v_adda from public.oil_shops where id=p_oil_shop_id and shop_type='external_supplier';if v_adda is null then raise exception 'OIL_SUPPLIER_NOT_FOUND';end if;
  if not public.is_super_admin() and v_adda is distinct from public.current_user_adda_id() then raise exception 'TENANT_MISMATCH';end if;
  if p_payment_date is null or v_advance<0 or v_now<0 or v_advance+v_now<=0 then raise exception 'INVALID_PAYMENT';end if;
  perform set_config('ut.oil_supplier_sync','on',true);
  if p_payment_id is null then insert into public.oil_supplier_payments(oil_shop_id,payment_date,amount,advance_used,payment_now,payment_method,reference_no,remarks) values(p_oil_shop_id,p_payment_date,v_advance+v_now,v_advance,v_now,nullif(btrim(p_payment_method),''),nullif(btrim(p_reference_no),''),nullif(btrim(p_remarks),'')) returning id into v_id;
  else select id into v_id from public.oil_supplier_payments where id=p_payment_id and oil_shop_id=p_oil_shop_id for update;if v_id is null then raise exception 'PAYMENT_NOT_FOUND_OR_SUPPLIER_CHANGE';end if;
    update public.oil_supplier_payments set payment_date=p_payment_date,amount=v_advance+v_now,advance_used=v_advance,payment_now=v_now,payment_method=nullif(btrim(p_payment_method),''),reference_no=nullif(btrim(p_reference_no),''),remarks=nullif(btrim(p_remarks),'') where id=v_id;end if;
  perform public.rebuild_oil_supplier_accounting(p_oil_shop_id);return v_id;
end $$;

create function public.delete_oil_supplier_payment(p_payment_id bigint) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare v_shop uuid;v_adda uuid;begin select p.oil_shop_id,s.adda_id into v_shop,v_adda from public.oil_supplier_payments p join public.oil_shops s on s.id=p.oil_shop_id where p.id=p_payment_id for update;
if v_shop is null then raise exception 'PAYMENT_NOT_FOUND';end if;if auth.uid() is null or public.current_user_role() not in('super_admin','adda_admin','operator') or (not public.is_super_admin() and v_adda is distinct from public.current_user_adda_id()) then raise exception 'AUTHORIZATION_FAILED';end if;
perform set_config('ut.oil_supplier_sync','on',true);delete from public.oil_supplier_payments where id=p_payment_id;perform public.rebuild_oil_supplier_accounting(v_shop);end $$;

create function public.ut_protect_oil_supplier_mutations() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin if coalesce(current_setting('ut.oil_supplier_sync',true),'')<>'on' then raise exception 'Oil supplier accounting rows must be changed through approved RPCs';end if;return case when tg_op='DELETE' then old else new end;end $$;
create trigger oil_supplier_bills_protect before insert or update or delete on public.oil_supplier_bills for each row execute function public.ut_protect_oil_supplier_mutations();
create trigger oil_supplier_payments_protect before insert or update or delete on public.oil_supplier_payments for each row execute function public.ut_protect_oil_supplier_mutations();
create trigger oil_supplier_allocations_protect before insert or update or delete on public.oil_supplier_payment_allocations for each row execute function public.ut_protect_oil_supplier_mutations();
create trigger oil_purchases_prepare_supplier_bill before insert or update or delete on public.oil_purchases for each row execute function public.ut_prepare_oil_supplier_source_mutation();
create trigger oil_vehicle_entries_prepare_supplier_bill before insert or update or delete on public.oil_vehicle_entries for each row execute function public.ut_prepare_oil_supplier_source_mutation();
create trigger oil_purchases_supplier_bill after insert or update or delete on public.oil_purchases for each row execute function public.ut_sync_oil_supplier_source_bill();
create trigger oil_vehicle_entries_supplier_bill after insert or update or delete on public.oil_vehicle_entries for each row execute function public.ut_sync_oil_supplier_source_bill();

create function public.ut_protect_oil_supplier_cashbook() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin if (case when tg_op='DELETE' then old.reference_type='oil_supplier_payment' else new.reference_type='oil_supplier_payment' or (tg_op='UPDATE' and old.reference_type='oil_supplier_payment') end) and coalesce(current_setting('ut.cashbook_sync',true),'')<>'on' then raise exception 'Oil supplier Cashbook entries must be changed from Oil Supplier Account';end if;return case when tg_op='DELETE' then old else new end;end $$;
create trigger cashbook_entries_protect_oil_supplier before insert or update or delete on public.cashbook_entries for each row execute function public.ut_protect_oil_supplier_cashbook();

-- Safe compatibility backfill: references authoritative bills only; it never changes source Oil rows or Cashbook.
do $$ begin
  perform set_config('ut.oil_supplier_sync','on',true);
  insert into public.oil_supplier_bills(adda_id,oil_shop_id,source_type,oil_purchase_id,bill_date,bill_no,amount,remaining_amount)
  select p.adda_id,p.oil_shop_id,'oil_purchase',p.id,p.purchase_date,p.bill_no,p.total_amount,p.total_amount from public.oil_purchases p join public.oil_shops s on s.id=p.oil_shop_id and s.shop_type='external_supplier' where p.total_amount>0 on conflict do nothing;
  insert into public.oil_supplier_bills(adda_id,oil_shop_id,source_type,oil_vehicle_entry_id,bill_date,bill_no,amount,remaining_amount)
  select e.adda_id,e.oil_shop_id,'oil_vehicle_entry',e.id,e.entry_date,e.bill_no,e.total_amount,e.total_amount from public.oil_vehicle_entries e join public.oil_shops s on s.id=e.oil_shop_id and s.shop_type='external_supplier' where e.source_type='external_shop' and e.total_amount>0 on conflict do nothing;
end $$;

revoke all on function public.rebuild_oil_supplier_accounting(uuid),public.ut_sync_oil_supplier_source_bill(),public.ut_prepare_oil_supplier_source_mutation(),public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text),public.delete_oil_supplier_payment(bigint),public.ut_protect_oil_supplier_mutations(),public.ut_protect_oil_supplier_cashbook() from public,anon,authenticated;
grant execute on function public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text),public.delete_oil_supplier_payment(bigint) to authenticated;

commit;
